11: // Generates a seamless procedural noise texture for powder-coated matte finish
12: const generateNoiseTexture = () => {
13:   if (typeof document === "undefined") return null;
14:   const size = 512;
15:   const canvas = document.createElement("canvas");
16:   canvas.width = size;
17:   canvas.height = size;
18:   const context = canvas.getContext("2d");
19:   if (!context) return null;
20: 
21:   const imgData = context.createImageData(size, size);
22:   for (let i = 0; i < imgData.data.length; i += 4) {
23:     const val = Math.floor(Math.random() * 255);
24:     imgData.data[i] = val;
25:     imgData.data[i + 1] = val;
26:     imgData.data[i + 2] = val;
27:     imgData.data[i + 3] = 255;
28:   }
29:   context.putImageData(imgData, 0, 0);
30: 
31:   const texture = new THREE.CanvasTexture(canvas);
32:   texture.wrapS = THREE.RepeatWrapping;
33:   texture.wrapT = THREE.RepeatWrapping;
34:   texture.repeat.set(10, 10);
35:   return texture;
36: };
