42:       const first = controls[0];
43:       const last = controls[controls.length - 1];
44:       if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
45:       else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
46:     };
47:     document.addEventListener("keydown", keyHandler);
48:     return () => {
49:       window.clearTimeout(timer);
